s=s[:a]+'''/**
 * Appends one audit row. Deliberately takes no `Actor`: the writer is usually
 * an event handler running outside a request, and the row's `actorId` comes
 * from the event payload rather than from an authenticated principal.
 *
 * `occurredAt` is when the action happened, not when the row is written — a
 * job that catches up later still files the entry under the original time.
 */
export async function record(
  orgId: OrgId,
  action: ActivityAction,
  input: ActivityRecordInput,
): Promise<ActivityEvent> {
  return activityRepo.insertActivity({
    orgId,
    action,
    actorId: input.actorId,
    subjectKind: input.subjectKind,
    subjectId: input.subjectId,
    projectId: input.projectId,
    summary: input.summary,
    metadata: input.metadata ?? {},
    occurredAt: resolveOccurredAt(input.occurredAt),
  });
}

function resolveOccurredAt(value: string | null | undefined): IsoTimestamp {
  if (typeof value === "string" && !Number.isNaN(Date.parse(value))) {
    return toIsoTimestamp(value);
  }
  return toIsoTimestamp(new Date());
}

/** Refuses a range that ends before it starts; a single instant is fine. */
function assertOrderedRange(
  since: string | undefined,
  until: string | undefined,
): void {
  if (since === undefined || until === undefined) return;
  const from = Date.parse(since);
  const to = Date.parse(until);
  if (Number.isNaN(from) || Number.isNaN(to) || from <= to) return;
  throw new ZodError([
    {
      code: "custom",
      path: ["until"],
      message: "until must not be earlier than since",
      input: until,
    },
  ]);
}

