a=s.index('/**\n * CSV (or JSON) export')
s=s[:a]+'''/**
 * Every entry of one organization inside `[since, until]`, newest first. Walks
 * the keyset cursor to the end so the result is complete however many rows
 * the range holds; the id guard keeps a row from ever being listed twice.
 */
export async function collectActivity(
  orgId: OrgId,
  since: IsoTimestamp,
  until: IsoTimestamp,
): Promise<readonly ActivityEvent[]> {
  assertOrderedRange(since, until);

  const events: ActivityEvent[] = [];
  const seen = new Set<string>();
  let cursor: string | null = null;

  for (;;) {
    const page: Page<ActivityEvent> = await activityRepo.listActivity({
      orgId,
      since,
      until,
      limit: EXPORT_PAGE_SIZE,
      cursor,
    });

    for (const event of page.items) {
      if (seen.has(event.id)) continue;
      seen.add(event.id);
      events.push(event);
    }

    if (page.nextCursor === null || page.items.length === 0) break;
    cursor = page.nextCursor;
  }

  return events;
}

/** The export's rows, for callers that render them themselves (the route). */
export async function listActivityForExport(
  actor: Actor,
  input: Pick<ExportActivityInput, "orgId" | "since" | "until">,
): Promise<readonly ActivityEvent[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "activity:export", activityResource(input.orgId));
  return collectActivity(input.orgId, input.since, input.until);
}

/**
 * CSV (or JSON) export of the audit log. Gated twice: on `activity:export`
 * for the role, and on the `csv_export` flag for the plan.
 */
export async function exportActivity(
  actor: Actor,
  input: ExportActivityInput,
): Promise<string> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "activity:export", activityResource(input.orgId));

  const org = await orgRepo.findOrgById(input.orgId);
  const flagEnabled = isEnabled("csv_export", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  if (input.format === "csv" && !flagEnabled) {
    throw new Error("CSV export is not included in this plan");
  }

  const events = await collectActivity(input.orgId, input.since, input.until);

  if (input.format === "json") {
    return JSON.stringify(events, null, 2);
  }

  return toCsv(
    events.map((event) => ({
      occurredAt: event.occurredAt,
      action: event.action,
      actorId: event.actorId,
      subjectKind: event.subjectKind,
      subjectId: event.subjectId,
      projectId: event.projectId,
      summary: event.summary,
    })),
    [...EXPORT_COLUMNS],
  );
}

/** Project of the issue a comment hangs off; `null` when it cannot be found. */
async function projectOfIssue(
  orgId: OrgId,
  issueId: IssueId,
  known: ProjectId | undefined,
): Promise<ProjectId | null> {
  if (known) return known;
  try {
    const issue = await issueRepo.findIssueById(orgId, issueId);
    return issue?.projectId ?? null;
  } catch {
    return null;
  }
}

