function resolveOccurredAt(value: string | null | undefined): IsoTimestamp {
  if (typeof value === "string" && !Number.isNaN(Date.parse(value))) {
    return toIsoTimestamp(value);
  }
  return toIsoTimestamp(new Date());
}

/** Refuses a range that ends before it starts; a single instant is fine. */
function assertOrderedRange(
  since: string | undefined,
  until: string | undefined,
): void {
  if (since === undefined || until === undefined) return;
  const from = Date.parse(since);
  const to = Date.parse(until);
  if (Number.isNaN(from) || Number.isNaN(to) || from <= to) return;
  throw new ZodError([
    {
      code: "custom",
      path: ["until"],
      message: "until must not be earlier than since",
      input: until,
    },
  ]);
}

